-- The two checklists published on 2026-11-27: When a Sale Is Pulling at You
-- (Spending) and When the Family Group Chat Gets Tense (Group Chats).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-27`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-a-sale-is-pulling-at-you', 'When a Sale Is Pulling at You', 'Open this when the discount codes are landing and you can feel yourself about to spend money you meant to keep. It slows the next ten minutes down enough for you to tell a want from a good deal.', 'Spending', '["Put it in the cart and walk away — Most of the pull is gone twenty minutes later.", "Check what you already own like it — The second one of something is rarely the fix.", "Work out the price in hours of your work — A number in hours lands differently than a number in dollars.", "Ask whether you wanted it last week — A want that arrived with the email is the sale talking.", "Unsubscribe from the one worst sender — The quickest saving is the message you never see.", "Say out loud what the money was for — Naming the plan it would come out of is usually enough.", "Buy the one thing on your actual list — Deciding in advance turns a spree into an errand.", "Forgive yourself quickly if you slip — A spiral of guilt costs more than the purchase did."]'::jsonb, 'as needed', array['Money', 'Habits', 'Boundaries']::text[], 1, '2026-11-27T16:00:00+00:00'::timestamptz),
  ('when-the-family-group-chat-gets-tense', 'When the Family Group Chat Gets Tense', 'Open this when a family thread has turned sharp and your phone keeps buzzing with things you would rather not read. It helps you decide what to answer, what to leave, and how to step back without making it worse.', 'Group Chats', '["Mute the thread for the rest of the day — Silence is not leaving, and the buzzing is half the problem.", "Read it once, not six times — Rereading sharpens a tone that may not have been there.", "Wait an hour before you type anything — The reply you would send now is the one you would regret.", "Answer the person, not the thread — A direct message settles what twenty people cannot.", "Leave the bait where it is — Not every message is addressed to you, even in a group.", "Say one warm thing if you say anything — A small kindness changes the temperature faster than an argument.", "Decide what you will not discuss here — Some subjects need a phone call rather than a thread.", "Step out of the chat if you need to — Leaving quietly is allowed, and you can say why later."]'::jsonb, 'as needed', array['Family', 'Boundaries', 'Communication']::text[], 1, '2026-11-27T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
